package com.example.customerrouting.common; import org.springframework.http.*; import org.springframework.web.bind.*; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*; @RestControllerAdvice public class ApiExceptionHandler { record Error(Instant timestamp,int status,String error,String message,List<String> details){} @ExceptionHandler(NoSuchElementException.class) ResponseEntity<Error> missing(Exception e){return ResponseEntity.status(404).body(new Error(Instant.now(),404,"NOT_FOUND",e.getMessage(),List.of()));} @ExceptionHandler({IllegalArgumentException.class,MethodArgumentNotValidException.class}) ResponseEntity<Error> bad(Exception e){List<String>d=e instanceof MethodArgumentNotValidException x?x.getBindingResult().getFieldErrors().stream().map(f->f.getField()+": "+f.getDefaultMessage()).toList():List.of();return ResponseEntity.badRequest().body(new Error(Instant.now(),400,"VALIDATION_ERROR","Request validation failed",d));} }
